//! 🧳️ A typed primary and every independent refusal keep their original backing through settlement.
use super::*;
use semio_framework_value::retirement::controlled::ControlledRetirement;
use semio_framework_value::ErasedSnapshotRetirement;
fn close<T:RetireOwned>(original:T,g:semio_framework_value::RetainedCloneGrant,maximum:u64){let mut owner=ControlledRetirement::new(original).ok().unwrap();for _ in 0..maximum{if owner.terminal_is_empty(){break}let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.step(g));let p=result.unwrap().progress();assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));}assert!(owner.terminal_is_empty());}
#[test]
fn native_snapshot_settlement_keeps_nonclone_primary_context_and_repeated_owner(){
 let(_,born,released)=semio_framework_trace_memory_testing::observe_backing(||{let bytes=std::hint::black_box(vec![0u8;73]);std::hint::black_box(&bytes);drop(bytes);});assert_eq!((born,released),(73,73));
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let p:RetainedCloneProgress=serde_json::from_value(f["progress"].clone()).unwrap();let messages=f["messages"].as_array().unwrap();let owned=|index:usize|ValueError::new(ValueRefusalKind::InvalidValue,messages[index].as_str().unwrap().to_owned());
 let primary=OriginalReceivingPrimary{primary:Some(owned(0)),quote_refusal:Some(owned(1)),allocation_refusal:Some(owned(2)),progress:p};let mut original=NativeSnapshotFailure::from(primary);original.context_refusal=Some(owned(3));let settlement=owned(4);let repeated=owned(5);
 let pointers=|failure:&NativeSnapshotFailure|{let primary=failure.receiving_primary().unwrap();[primary.primary.as_ref().unwrap().message.as_ptr(),primary.quote_refusal.as_ref().unwrap().message.as_ptr(),primary.allocation_refusal.as_ref().unwrap().message.as_ptr(),failure.context_refusal().unwrap().message.as_ptr()]};let originals=pointers(&original);let settlement_pointer=settlement.message.as_ptr();let repeated_pointer=repeated.message.as_ptr();
 let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||original.with_settlement_refusal(settlement));assert_eq!((born,released),(f["expected"]["foldAllocationBytes"].as_u64().unwrap()as usize,f["expected"]["foldReleaseBytes"].as_u64().unwrap()as usize));assert_eq!(result.is_ok(),f["expected"]["accepted"].as_bool().unwrap());let original=result.unwrap();assert_eq!(pointers(&original),originals);assert_eq!(original.settlement_refusal().unwrap().message.as_ptr(),settlement_pointer);assert_eq!(original.retained_progress(),p);
 let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||original.with_settlement_refusal(repeated));assert_eq!((born,released),(0,0));assert_eq!(result.is_ok(),f["expected"]["repeatAccepted"].as_bool().unwrap());let(original,repeated)=result.unwrap_err();assert_eq!(pointers(&original),originals);assert_eq!(original.settlement_refusal().unwrap().message.as_ptr(),settlement_pointer);assert_eq!(repeated.message.as_ptr(),repeated_pointer);assert_eq!(original.retained_progress(),p);assert_eq!(original.message(),messages[0].as_str().unwrap());assert_eq!(original.receipt_refusal(),None);
 let g=serde_json::from_value(f["closeGrant"].clone()).unwrap();let maximum=f["maximumTurns"].as_u64().unwrap();close(original,g,maximum);close(repeated,g,maximum);
}
